(()=>{'use strict';
let libraryPromise;function loadScript(src){return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>{script.remove();reject(Error('PDF library unavailable'))};document.head.append(script)})}async function ensureLibraries(){if(!libraryPromise)libraryPromise=(async()=>{if(!window.jspdf?.jsPDF)await loadScript('/vendor/jspdf.umd.min.js');if(!window.dracoReceiptFonts)await loadScript('/receipt-fonts.js')})().catch(e=>{libraryPromise=null;throw e});return libraryPromise}
const currency=n=>'$'+Number(n).toLocaleString('es-CO')+' COP';
async function photoData(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=400;canvas.height=400;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,400,400);const r=Math.min(380/img.width,380/img.height);c.drawImage(img,(400-img.width*r)/2,(400-img.height*r)/2,img.width*r,img.height*r);resolve(canvas.toDataURL('image/jpeg',.9))};img.onerror=()=>reject(Error('Photo unavailable'));img.src=src})}
window.createDracoReceipt=async function({items,customer,reference,createdAt,preparedImages}){await ensureLibraries();if(!window.jspdf?.jsPDF)throw Error('PDF unavailable');if(!items.length||items.some(p=>!p.sku||!Number.isFinite(p.price)||p.price<0||!Number.isInteger(p.quantity)||p.quantity<1||p.quantity>99))throw Error('Invalid order');const doc=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});if(window.dracoReceiptFonts){for(const style of ['normal','bold']){doc.addFileToVFS('Draco-'+style+'.ttf',window.dracoReceiptFonts[style]);doc.addFont('Draco-'+style+'.ttf','Draco',style)}}const font=window.dracoReceiptFonts?'Draco':'helvetica';doc.setProperties({title:'Pedido '+reference,subject:'Resumen de pedido pendiente de confirmación',creator:'Anillos Draco'});const total=items.reduce((n,p)=>n+p.price*p.quantity,0),units=items.reduce((n,p)=>n+p.quantity,0);let y=0;function header(){doc.setFillColor(16,16,17);doc.rect(0,0,210,38,'F');doc.setTextColor(247,247,247);doc.setFont(font,'bold');doc.setFontSize(20);doc.text('ANILLOS DRACO',15,18);doc.setFontSize(9);doc.setFont(font,'normal');doc.text('RESUMEN DE PEDIDO',15,28);doc.setTextColor(16,16,17);doc.setFontSize(9);doc.text(reference,195,46,{align:'right'});y=53}function section(title){doc.setFont(font,'bold');doc.setFontSize(11);doc.text(title,15,y);y+=8}header();doc.setFontSize(9);doc.text(createdAt,15,46);section('Cliente y entrega');doc.setFont(font,'normal');doc.setFontSize(10);for(const [label,value]of [['Nombre',customer.name],['Teléfono',customer.phone],['Ubicación',customer.municipality+', '+customer.department],['Dirección',customer.address]]){const lines=doc.splitTextToSize(label+': '+String(value||''),178);doc.text(lines,15,y);y+=lines.length*5+2}y+=4;section('Productos');for(const p of items){const name=doc.splitTextToSize(p.name,100);const rowHeight=Math.max(39,name.length*5+21);if(y+rowHeight>259){doc.addPage();header();section('Productos (continuación)')}doc.setDrawColor(223,218,210);doc.line(15,y-2,195,y-2);let photo=null;try{photo=preparedImages?.[p.id]||await photoData(p.image)}catch{}if(photo)doc.addImage(photo,'JPEG',15,y,30,30,undefined,'FAST');else{doc.setFontSize(8);doc.setTextColor(100);doc.text('Foto no disponible',15,y+15)}doc.setTextColor(16,16,17);doc.setFont(font,'bold');doc.setFontSize(10);doc.text(name,50,y+5);let ty=y+name.length*5+7;doc.setFont(font,'normal');doc.setFontSize(9);doc.text('SKU: '+p.sku,50,ty);doc.text('Cantidad: '+p.quantity+'  |  Unidad: '+currency(p.price),50,ty+6);doc.setFont(font,'bold');doc.setFontSize(10);doc.text(currency(p.price*p.quantity),195,y+rowHeight-9,{align:'right'});y+=rowHeight}if(y+54>277){doc.addPage();header()}y+=6;doc.setFillColor(244,241,236);doc.roundedRect(15,y,180,29,3,3,'F');doc.setFont(font,'normal');doc.setFontSize(10);doc.text(units+' unidades · '+items.length+' modelos',21,y+9);doc.text('Envío a Colombia: incluido',21,y+18);doc.setFont(font,'bold');doc.setFontSize(13);doc.text('TOTAL '+currency(total),189,y+21,{align:'right'});y+=38;doc.setFont(font,'normal');doc.setFontSize(9);doc.setTextColor(90);doc.text(doc.splitTextToSize('Pendiente de confirmación. Este resumen no acredita pago, no confirma disponibilidad y no es una factura fiscal. Acuerda entrega y pago con Draco por WhatsApp al +57 321 558 7953.',180),15,y);const count=doc.getNumberOfPages();for(let page=1;page<=count;page++){doc.setPage(page);doc.setDrawColor(225);doc.line(15,279,195,279);doc.setTextColor(115);doc.setFont(font,'normal');doc.setFontSize(8);doc.text('ANILLOS DRACO · '+reference,15,285);doc.text(page+' / '+count,195,285,{align:'right'})}return{blob:doc.output('blob'),reference,pages:count,total,units};};
})();
